function API.GetWow(wowId)
    return API.WOW[tonumber(wowId)]
end

function API.GetForEntry(entry)
    return type(entry) == "table" and API.GetWow(entry.wow) or nil
end

function API.GetName(info)
    return type(info) == "table" and (info.name or info.classicName) or nil
end

function API.GetIcon(info)
    return type(info) == "table" and info.icon or nil
end
